import fs from 'fs';
import path from 'path';

const SKILLS_BASE = path.join(__dirname, '../../../../Skills');
const AGENT_MD_PATH = path.join(__dirname, '../../AGENT.md');

const DEFAULT_AGENT_PROMPT =
  "You are OkVevo's AI assistant. Help users create educational videos. Be helpful, clear, and concise.";

const SKILL_PATHS: Record<string, string> = {
  hyperframes: path.join(SKILLS_BASE, 'hyperframes/.agents/skills/hyperframes/SKILL.md'),
  'manim-video': path.join(SKILLS_BASE, 'manim-video/SKILL.md'),
  'edu-video': path.join(SKILLS_BASE, 'edu-video/SKILL.md'),
};

function getLastMessageText(messages: any[]): string {
  if (messages.length === 0) return '';

  const last = messages[messages.length - 1];

  if (typeof last.content === 'string') {
    return last.content;
  }

  if (Array.isArray(last.parts)) {
    return last.parts
      .filter((part: { type: string }) => part.type === 'text')
      .map((part: { text: string }) => part.text)
      .join('');
  }

  return '';
}

export function loadAgentMd(): string {
  try {
    if (fs.existsSync(AGENT_MD_PATH)) {
      return fs.readFileSync(AGENT_MD_PATH, 'utf-8');
    }
  } catch {
    // fall through to default
  }
  return DEFAULT_AGENT_PROMPT;
}

export function detectSkill(messages: any[]): string | null {
  const text = getLastMessageText(messages).toLowerCase();

  if (
    text.includes('edu-video') ||
    text.includes('/edu-video') ||
    text.includes('educational video') ||
    text.includes('generate educational video') ||
    text.includes('teacher video') ||
    text.includes('turn my video into')
  ) {
    return 'edu-video';
  }
  if (text.includes('hyperframes') || text.includes('/hyperframes')) {
    return 'hyperframes';
  }
  if (text.includes('manim') || text.includes('/manim')) {
    return 'manim-video';
  }

  return null;
}

export function resolveSkill(messages: any[], skillId?: string): string | null {
  if (skillId) return skillId;
  return detectSkill(messages);
}

export function loadSkillMd(skillName: string): string {
  const skillPath = SKILL_PATHS[skillName];
  if (!skillPath) return '';

  try {
    if (fs.existsSync(skillPath)) {
      return fs.readFileSync(skillPath, 'utf-8');
    }
  } catch {
    // return empty string per spec
  }

  return '';
}
